  ('Slow Horses', 'https://image.tmdb.org/t/p/w342/5RuZZIouptatjV96BdPmKmRsnGg.jpg'),
  ('Poor Things', 'https://image.tmdb.org/t/p/w342/kCGlIMHnOm8JPXq3rXM6c5wMxcT.jpg'),
  ('Shogun', 'https://image.tmdb.org/t/p/w342/7O4iVfOMQmdCSxhOg1WnzG1AgYT.jpg'),
  ('The Last of Us', 'https://image.tmdb.org/t/p/w342/dmo6TYuuJgaYinXBPjrgG9mB5od.jpg'),
  ('Everything Everywhere All at Once', 'https://image.tmdb.org/t/p/w342/u68AjlvlutfEIcpmbYpKcdi09ut.jpg'),
